import{_ as l,o as e,c as i,O as o}from"./chunks/framework.db831a78.js";const m=JSON.parse('{"title":"JVM","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/02-JVM.md","filePath":"interview/后端/Java/02-JVM.md","lastUpdated":null}'),r={name:"interview/后端/Java/02-JVM.md"};function t(h,a,d,c,n,u){return e(),i("div",null,a[0]||(a[0]=[o('<h1 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 源码关键点 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="jvm-内存区域划分-各区域作用-哪些会-oom-★★★" tabindex="-1">JVM 内存区域划分，各区域作用，哪些会 OOM ★★★ <a class="header-anchor" href="#jvm-内存区域划分-各区域作用-哪些会-oom-★★★" aria-label="Permalink to &quot;JVM 内存区域划分，各区域作用，哪些会 OOM ★★★&quot;">​</a></h2><h3 id="内存区域-5-块-直接内存" tabindex="-1">内存区域（5 块 + 直接内存） <a class="header-anchor" href="#内存区域-5-块-直接内存" aria-label="Permalink to &quot;内存区域（5 块 + 直接内存）&quot;">​</a></h3><ul><li>线程私有： <ul><li>程序计数器：记录当前线程执行字节码的位置（行号指示器），分支/循环/跳转/异常都依赖它；是唯一不 OOM 的区域。</li><li>虚拟机栈：每个方法一个栈帧（局部变量表、操作数栈、动态链接、返回地址）；栈深度超过限制抛 <code>StackOverflowError</code>，无法再扩展抛 <code>OutOfMemoryError</code>。</li><li>本地方法栈：为 native 方法服务（HotSpot 把本地方法栈和虚拟机栈合并）。</li></ul></li><li>线程共享： <ul><li>堆：存放对象实例，是 GC 主战场；OOM：<code>Java heap space</code>。</li><li>方法区/元空间：存类元数据、常量、静态变量、即时编译后的代码；OOM：<code>Metaspace</code>（JDK8+）/ <code>PermGen space</code>（JDK7 及以前）。</li><li>运行时常量池：方法区的一部分，存编译期生成的字面量和符号引用。</li></ul></li></ul><h3 id="直接内存" tabindex="-1">直接内存 <a class="header-anchor" href="#直接内存" aria-label="Permalink to &quot;直接内存&quot;">​</a></h3><ul><li>不是 JVM 运行时数据区，但属于 JVM 内存范畴；NIO 的 <code>ByteBuffer.allocateDirect</code> 分配堆外内存；OOM：<code>Direct buffer memory</code>，受 <code>-XX:MaxDirectMemorySize</code> 控制。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「栈和堆的区别？」→ 栈存方法调用与局部变量（线程私有、生命周期短、后进先出）；堆存对象（线程共享、由 GC 管理）。</li><li>「哪些区域会 OOM？」→ 堆、栈（StackOverflowError/OOM）、元空间、直接内存；程序计数器不会。</li></ul><h3 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>JDK8 用元空间替代永久代，元空间在本地内存、默认无上限（受物理内存限制），需 <code>-XX:MaxMetaspaceSize</code> 限制，否则动态生成类过多会打爆系统内存。</li></ul><hr><h2 id="对象创建过程-对象内存布局-对象头-★★☆" tabindex="-1">对象创建过程，对象内存布局，对象头 ★★☆ <a class="header-anchor" href="#对象创建过程-对象内存布局-对象头-★★☆" aria-label="Permalink to &quot;对象创建过程，对象内存布局，对象头 ★★☆&quot;">​</a></h2><h3 id="创建过程-从-new-到对象可用" tabindex="-1">创建过程（从 new 到对象可用） <a class="header-anchor" href="#创建过程-从-new-到对象可用" aria-label="Permalink to &quot;创建过程（从 new 到对象可用）&quot;">​</a></h3><ol><li>类加载检查：new 时先去常量池找符号引用，检查类是否已加载/解析/初始化，未加载则先执行类加载。</li><li>分配内存：在堆中划一块空间，两种方式： <ul><li>指针碰撞：堆内存规整（有 Serial/ParNew 等带压缩的收集器），用指针分割已用/空闲内存，指针后移。</li><li>空闲列表：堆内存不规整（CMS 等标记清除），JVM 维护空闲列表，从列表找合适块。</li><li>并发分配安全：CAS + 失败重试，或 TLAB（线程本地分配缓冲，各线程先在私有缓冲分配，减少竞争）。</li></ul></li><li>零值初始化：把分配的内存空间初始化为零值（保证实例字段不赋值也有默认值）。</li><li>设置对象头：设置哈希码（延迟到首次调用 hashCode 才生成）、GC 分代年龄、锁状态标志、类型指针等。</li><li>执行 <code>&lt;init&gt;</code>：按构造器初始化字段，真正意义上的「初始化」。</li></ol><h3 id="对象内存布局-三部分" tabindex="-1">对象内存布局（三部分） <a class="header-anchor" href="#对象内存布局-三部分" aria-label="Permalink to &quot;对象内存布局（三部分）&quot;">​</a></h3><ol><li>对象头： <ul><li>Mark Word（标记字）：存 hashCode、GC 分代年龄、锁状态标志、偏向锁线程 ID、偏向时间戳等（根据锁状态复用不同位）。</li><li>类型指针（Klass Pointer）：指向类元数据；数组还有长度字段。</li></ul></li><li>实例数据：对象的字段，含父类继承的字段；相同宽度的字段会尽量分配在一起（字段重排序）。</li><li>对齐填充：保证对象大小是 8 字节的整数倍（HotSpot 要求）。</li></ol><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「对象头里存了什么？」→ Mark Word + 类型指针，Mark Word 里 hashCode、GC 年龄、锁状态等是复用的。</li><li>「TLAB 是什么？为什么有？」→ 线程本地分配缓冲，减少多线程并发分配内存时的锁竞争（CAS 竞争），提升分配效率。</li></ul><hr><h2 id="如何判断对象是垃圾-四种引用-★★★" tabindex="-1">如何判断对象是垃圾；四种引用 ★★★ <a class="header-anchor" href="#如何判断对象是垃圾-四种引用-★★★" aria-label="Permalink to &quot;如何判断对象是垃圾；四种引用 ★★★&quot;">​</a></h2><h3 id="判断算法" tabindex="-1">判断算法 <a class="header-anchor" href="#判断算法" aria-label="Permalink to &quot;判断算法&quot;">​</a></h3><ul><li>引用计数法：每个对象一个计数器，被引用 +1，失效 -1，为 0 回收；缺点：无法解决循环引用（A↔B 互相引用，计数永不为 0）。</li><li>可达性分析（HotSpot 采用）：从 GC Roots 出发，沿引用链可达的对象存活，不可达的为垃圾。</li></ul><h3 id="gc-roots-有哪些" tabindex="-1">GC Roots 有哪些 <a class="header-anchor" href="#gc-roots-有哪些" aria-label="Permalink to &quot;GC Roots 有哪些&quot;">​</a></h3><ul><li>虚拟机栈（栈帧局部变量表）中引用的对象。</li><li>方法区中「类静态属性」引用的对象、常量引用的对象。</li><li>本地方法栈中 native 方法引用的对象。</li><li>JVM 内部引用（基本类型对应的 Class 对象、常驻异常对象、系统类加载器）、同步锁持有的对象等。</li></ul><h3 id="四种引用" tabindex="-1">四种引用 <a class="header-anchor" href="#四种引用" aria-label="Permalink to &quot;四种引用&quot;">​</a></h3><ul><li>强引用：普通 <code>Object o = new Object()</code>，只要强引用存在就绝不回收。</li><li>软引用（SoftReference）：内存不足（OOM 前）才回收，适合做缓存。</li><li>弱引用（WeakReference）：只要发生 GC 就回收，如 WeakHashMap、ThreadLocal 的 key。</li><li>虚引用（PhantomReference）：无法通过它获取对象，仅用于对象被回收时收到通知（配合引用队列 ReferenceQueue 做回收跟踪，如 NIO 直接内存清理）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么不用引用计数？」→ 循环引用无法回收。</li><li>「软引用和弱引用区别？」→ 软引用在内存不足时才回收，弱引用 GC 即回收。</li></ul><hr><h2 id="gc-三大算法-★★★" tabindex="-1">GC 三大算法 ★★★ <a class="header-anchor" href="#gc-三大算法-★★★" aria-label="Permalink to &quot;GC 三大算法 ★★★&quot;">​</a></h2><h3 id="标记清除-mark-sweep" tabindex="-1">标记清除（Mark-Sweep） <a class="header-anchor" href="#标记清除-mark-sweep" aria-label="Permalink to &quot;标记清除（Mark-Sweep）&quot;">​</a></h3><ul><li>过程：标记存活对象 → 清除未标记对象。</li><li>优点：简单；缺点：产生内存碎片、效率不稳定（标记和清除都需扫描）。</li></ul><h3 id="复制-copying" tabindex="-1">复制（Copying） <a class="header-anchor" href="#复制-copying" aria-label="Permalink to &quot;复制（Copying）&quot;">​</a></h3><ul><li>过程：内存分两块，把存活对象复制到另一块，然后清空当前块。</li><li>优点：无碎片、效率高（只需移动存活对象）；缺点：浪费一半空间（实际是 Eden:S0:S1 = 8:1:1，只浪费 10%）。</li><li>用于新生代（对象朝生夕死，存活少，复制成本低）。</li></ul><h3 id="标记整理-mark-compact" tabindex="-1">标记整理（Mark-Compact） <a class="header-anchor" href="#标记整理-mark-compact" aria-label="Permalink to &quot;标记整理（Mark-Compact）&quot;">​</a></h3><ul><li>过程：标记存活对象 → 把存活对象向一端移动，清理边界外内存。</li><li>优点：无碎片；缺点：移动对象成本高（需 STW 暂停所有线程）。</li><li>用于老年代。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么新生代用复制、老年代用标记整理？」→ 新生代存活率低，复制只需搬少量对象；老年代存活率高，复制成本大，用标记整理避免碎片。</li><li>「三色标记是什么？」→ 见下文，是并发可达性分析的算法。</li></ul><hr><h2 id="常见垃圾收集器-★★★" tabindex="-1">常见垃圾收集器 ★★★ <a class="header-anchor" href="#常见垃圾收集器-★★★" aria-label="Permalink to &quot;常见垃圾收集器 ★★★&quot;">​</a></h2><h3 id="分类与演进" tabindex="-1">分类与演进 <a class="header-anchor" href="#分类与演进" aria-label="Permalink to &quot;分类与演进&quot;">​</a></h3><ul><li>Serial / Serial Old：单线程，新生代复制 / 老年代标记整理，STW 明显，客户端小内存用。</li><li>ParNew：Serial 的多线程版本（新生代并行），常配 CMS。</li><li>Parallel Scavenge / Parallel Old：多线程，关注吞吐量（适合后台计算型），JDK8 默认组合。</li><li>CMS：并发标记清除，追求低停顿；缺点：内存碎片、浮动垃圾、并发阶段占用 CPU，JDK9 废弃。</li><li>G1：Region 分区 + 复制，可预测停顿（<code>-XX:MaxGCPauseMillis</code>），JDK9 默认。</li><li>ZGC：着色指针 + 读屏障，停顿亚毫秒级，支持超大堆（TB 级），JDK15 量产。</li></ul><h3 id="g1-核心" tabindex="-1">G1 核心 <a class="header-anchor" href="#g1-核心" aria-label="Permalink to &quot;G1 核心&quot;">​</a></h3><ul><li>把堆划分为多个大小相等的 Region，不再物理区分新生代/老年代（逻辑上仍分）。</li><li>回收时优先回收「垃圾最多的 Region」（Garbage First 名字由来），支持可预测停顿模型。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CMS 为什么会产生浮动垃圾？」→ 并发标记阶段用户线程继续运行产生的新垃圾，本轮 GC 无法处理，留待下次。</li><li>「G1 和 CMS 区别？」→ G1 分 Region、可预测停顿、无碎片（复制）、能处理大堆；CMS 标记清除有碎片、停顿不可控。</li><li>「ZGC 为什么停顿极低？」→ 着色指针 + 读屏障，绝大部分工作并发执行，STW 只发生在极短阶段。</li></ul><h3 id="易错点-1" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-1" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>没有「最好」的收集器，只有「最适合场景」的：低延迟选 ZGC/Shenandoah，可控停顿选 G1，吞吐优先选 Parallel，小内存选 Serial。</li></ul><hr><h2 id="类加载全过程-双亲委派模型-破坏双亲委派-★★★" tabindex="-1">类加载全过程；双亲委派模型；破坏双亲委派 ★★★ <a class="header-anchor" href="#类加载全过程-双亲委派模型-破坏双亲委派-★★★" aria-label="Permalink to &quot;类加载全过程；双亲委派模型；破坏双亲委派 ★★★&quot;">​</a></h2><h3 id="类加载过程-5-阶段" tabindex="-1">类加载过程（5 阶段） <a class="header-anchor" href="#类加载过程-5-阶段" aria-label="Permalink to &quot;类加载过程（5 阶段）&quot;">​</a></h3><ol><li>加载：通过类全限定名获取字节流，转为方法区的运行时数据结构，在堆生成 Class 对象。</li><li>验证：校验字节码格式、语义（如 final 不被重写）等，保证安全。</li><li>准备：为静态变量分配内存并设零值（不执行赋值，赋值在初始化阶段）。</li><li>解析：把常量池的符号引用替换为直接引用。</li><li>初始化：执行类构造器 <code>&lt;clinit&gt;</code>（静态变量赋值 + 静态代码块）。</li></ol><h3 id="双亲委派模型" tabindex="-1">双亲委派模型 <a class="header-anchor" href="#双亲委派模型" aria-label="Permalink to &quot;双亲委派模型&quot;">​</a></h3><ul><li>加载请求先委托父加载器（Bootstrap → Extension → Application → 自定义），父加载器加载不了才由子加载器自己加载。</li><li>作用：① 避免类重复加载；② 保护核心类（防止自定义类伪装成 <code>java.lang.String</code>）。</li></ul><h3 id="三类加载器" tabindex="-1">三类加载器 <a class="header-anchor" href="#三类加载器" aria-label="Permalink to &quot;三类加载器&quot;">​</a></h3><ul><li>Bootstrap ClassLoader（启动类加载器）：加载 <code>&lt;JAVA_HOME&gt;/lib</code> 核心类库，C++ 实现，无法直接获取。</li><li>Extension/Platform ClassLoader：加载 <code>lib/ext</code> 或 <code>jre/lib/ext</code>。</li><li>Application ClassLoader（系统类加载器）：加载 classpath 下的类。</li></ul><h3 id="破坏双亲委派的场景" tabindex="-1">破坏双亲委派的场景 <a class="header-anchor" href="#破坏双亲委派的场景" aria-label="Permalink to &quot;破坏双亲委派的场景&quot;">​</a></h3><ul><li>JDBC：SPI 机制，<code>DriverManager</code> 由 Bootstrap 加载，但驱动实现类在 classpath，需用「线程上下文类加载器」反向加载。</li><li>Tomcat：各 Web 应用的类隔离，<code>WebAppClassLoader</code> 优先自己加载（web 应用自己的 class 优先于父加载器的）。</li><li>OSGi：模块化热部署，每个模块独立类加载器。</li><li>热部署/热替换框架。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「准备阶段和初始化阶段对静态变量的区别？」→ 准备阶段设零值（如 <code>static int i = 1</code> 此时 i=0），初始化阶段才真正赋 1。</li><li>「双亲委派是必须的吗？」→ 不是，可以破坏（如 JDBC/Tomcat），是为了安全和避免重复加载的设计。</li></ul><hr><h2 id="oom-常见场景-jmap、jstack-工具作用-★★★" tabindex="-1">OOM 常见场景；jmap、jstack 工具作用 ★★★ <a class="header-anchor" href="#oom-常见场景-jmap、jstack-工具作用-★★★" aria-label="Permalink to &quot;OOM 常见场景；jmap、jstack 工具作用 ★★★&quot;">​</a></h2><h3 id="oom-场景" tabindex="-1">OOM 场景 <a class="header-anchor" href="#oom-场景" aria-label="Permalink to &quot;OOM 场景&quot;">​</a></h3><ul><li>堆溢出：对象过多/大对象（<code>Java heap space</code>）。</li><li>栈溢出：递归过深（<code>StackOverflowError</code>）。</li><li>元空间溢出：动态生成类过多（CGLIB 大量代理、频繁热部署）（<code>Metaspace</code>）。</li><li>GC 开销超限：GC 占用大量时间但回收甚少（<code>GC overhead limit exceeded</code>）。</li><li>直接内存溢出：NIO DirectBuffer 过多（<code>Direct buffer memory</code>）。</li></ul><h3 id="排查工具" tabindex="-1">排查工具 <a class="header-anchor" href="#排查工具" aria-label="Permalink to &quot;排查工具&quot;">​</a></h3><ul><li>jmap：查看堆内存、生成堆快照（<code>jmap -dump:format=b,file=heap.hprof &lt;pid&gt;</code>），配合 MAT 分析。</li><li>jstack：打印线程栈（<code>jstack &lt;pid&gt;</code>），检测死锁（输出里有 <code>Found one Java-level deadlock</code>）、定位 CPU 高线程。</li><li>jstat：查看 GC 情况、类加载、编译等统计。</li><li>jinfo：查看/调整 JVM 参数。</li><li>jps：列出 Java 进程。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CPU 飙高怎么排查？」→ top 找高 CPU 进程 → <code>top -Hp pid</code> 找高 CPU 线程 → 线程号转十六进制 → <code>jstack</code> 里找对应线程（nid），定位代码（死循环/频繁 GC/锁竞争）。</li></ul><hr><h2 id="逃逸分析-栈上分配-★★☆" tabindex="-1">逃逸分析，栈上分配 ★★☆ <a class="header-anchor" href="#逃逸分析-栈上分配-★★☆" aria-label="Permalink to &quot;逃逸分析，栈上分配 ★★☆&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>逃逸分析：分析对象的作用域，判断它是否会「逃出」方法或线程。</li><li>逃逸：对象被方法外部引用（返回、赋给外部字段）即逃逸；只在方法内部使用则「不逃逸」。</li></ul><h3 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h3><ul><li>栈上分配：不逃逸的对象分配在栈帧，随方法结束销毁，减轻 GC 压力。</li><li>标量替换：把对象拆成基本类型（标量）分别分配，进一步优化。</li><li>同步消除：确定对象不会逃逸时，去掉对它的同步锁。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「逃逸分析默认开启吗？」→ HotSpot 默认开启（<code>-XX:+DoEscapeAnalysis</code>），但栈上分配实际是通过标量替换实现的（HotSpot 没有真正的栈上分配）。</li></ul><hr><h2 id="jvm-常用调优参数-★★☆" tabindex="-1">JVM 常用调优参数 ★★☆ <a class="header-anchor" href="#jvm-常用调优参数-★★☆" aria-label="Permalink to &quot;JVM 常用调优参数 ★★☆&quot;">​</a></h2><ul><li>堆：<code>-Xms</code>（初始）、<code>-Xmx</code>（最大）、<code>-Xmn</code>（新生代）；一般 <code>-Xms</code> 与 <code>-Xmx</code> 相等避免动态扩容。</li><li>栈：<code>-Xss</code>（每个线程栈大小）。</li><li>元空间：<code>-XX:MetaspaceSize</code>、<code>-XX:MaxMetaspaceSize</code>。</li><li>GC 选择：<code>-XX:+UseG1GC</code>、<code>-XX:+UseZGC</code> 等。</li><li>停顿目标：<code>-XX:MaxGCPauseMillis</code>（G1）。</li><li>日志：<code>-Xlog:gc*</code>。</li><li>OOM 快照：<code>-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=...</code>。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「调优思路？」→ 先量后调（看 GC 日志/监控），别盲目加内存；先确认是内存、CPU、GC 还是 IO 瓶颈，再针对性调参数。</li></ul><hr><h2 id="jmm-与-jvm-内存模型的区别-★★★" tabindex="-1">JMM 与 JVM 内存模型的区别 ★★★ <a class="header-anchor" href="#jmm-与-jvm-内存模型的区别-★★★" aria-label="Permalink to &quot;JMM 与 JVM 内存模型的区别 ★★★&quot;">​</a></h2><h3 id="两个「内存模型」别混淆" tabindex="-1">两个「内存模型」别混淆 <a class="header-anchor" href="#两个「内存模型」别混淆" aria-label="Permalink to &quot;两个「内存模型」别混淆&quot;">​</a></h3><ul><li>JVM 内存模型（运行时数据区）：是「数据存储的物理划分」，分堆/栈/方法区/程序计数器等，回答「数据放在哪」。</li><li>JMM（Java 内存模型）：是「并发规范」，规定多线程下共享变量的可见性、有序性，抽象出主内存与工作内存，回答「多线程怎么安全地读写共享变量」。</li></ul><h3 id="jmm-核心" tabindex="-1">JMM 核心 <a class="header-anchor" href="#jmm-核心" aria-label="Permalink to &quot;JMM 核心&quot;">​</a></h3><ul><li>主内存：所有线程共享；工作内存：每个线程私有副本，线程对变量的操作在工作内存进行，再同步回主内存。</li><li>通过 volatile / final / synchronized / lock 建立 happens-before 规则，保证可见性与有序性。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「JMM 是真实存在的内存吗？」→ 不是物理内存，是一套抽象规范，规定了多线程读写共享变量的语义。</li></ul><hr><h2 id="元空间-vs-永久代、字符串常量池位置-★★☆" tabindex="-1">元空间 vs 永久代、字符串常量池位置 ★★☆ <a class="header-anchor" href="#元空间-vs-永久代、字符串常量池位置-★★☆" aria-label="Permalink to &quot;元空间 vs 永久代、字符串常量池位置 ★★☆&quot;">​</a></h2><ul><li>JDK7 起字符串常量池从永久代移到堆。</li><li>JDK8 用元空间（本地内存）替代永久代（方法区逻辑概念保留）。</li><li>好处：元空间默认不受 <code>-XX:MaxPermSize</code> 限制，由本机内存分配，避免永久代 OOM。</li><li>永久代 OOM 场景（动态生成类过多）在元空间依然可能 OOM（Metaspace），但默认上限更大、可独立调优。</li></ul><hr><h2 id="直接内存-★★☆" tabindex="-1">直接内存 ★★☆ <a class="header-anchor" href="#直接内存-★★☆" aria-label="Permalink to &quot;直接内存 ★★☆&quot;">​</a></h2><ul><li>NIO 通过 <code>ByteBuffer.allocateDirect</code> 分配堆外内存，避免 GC 和堆内外的数据复制（提升 IO 性能）。</li><li>不受堆大小管控，满时触发 OOM（Direct buffer memory），用 <code>-XX:MaxDirectMemorySize</code> 控制。</li><li>清理：依赖虚引用 + Cleaner 机制，触发 GC 时回收；手动可调 <code>((DirectBuffer)buf).cleaner().clean()</code>。</li></ul><hr><h2 id="三色标记、对象进入老年代条件、stw-★★☆" tabindex="-1">三色标记、对象进入老年代条件、STW ★★☆ <a class="header-anchor" href="#三色标记、对象进入老年代条件、stw-★★☆" aria-label="Permalink to &quot;三色标记、对象进入老年代条件、STW ★★☆&quot;">​</a></h2><h3 id="三色标记-并发可达性分析" tabindex="-1">三色标记（并发可达性分析） <a class="header-anchor" href="#三色标记-并发可达性分析" aria-label="Permalink to &quot;三色标记（并发可达性分析）&quot;">​</a></h3><ul><li>白：未访问；灰：已访问但子对象未扫描完；黑：子对象已扫描。</li><li>漏标（对象被误回收）需写屏障补救：CMS 用「增量更新」，G1 用「SATB（原始快照）」。</li></ul><h3 id="对象进入老年代的条件" tabindex="-1">对象进入老年代的条件 <a class="header-anchor" href="#对象进入老年代的条件" aria-label="Permalink to &quot;对象进入老年代的条件&quot;">​</a></h3><ul><li>年龄达到阈值（默认 15，<code>-XX:MaxTenuringThreshold</code>）。</li><li>大对象直接进老年代（<code>-XX:PretenureSizeThreshold</code>）。</li><li>Survivor 空间不足：同龄对象总和超过 Survivor 一半时，年龄 ≥ 该值的对象直接进老年代（动态年龄判断）。</li><li>长期存活对象晋升。</li></ul><h3 id="stw-stop-the-world" tabindex="-1">STW（Stop The World） <a class="header-anchor" href="#stw-stop-the-world" aria-label="Permalink to &quot;STW（Stop The World）&quot;">​</a></h3><ul><li>GC 时暂停所有用户线程（在安全点 Safepoint），保证一致性；追求低停顿就是减少 STW 时间。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么需要 STW？」→ GC 移动对象/标记时用户线程若继续运行会破坏一致性，必须暂停。</li><li>「哪些 GC 会 STW？」→ 所有 GC 都会有（哪怕 ZGC 也有极短的 STW），只是时间长短不同。</li></ul>',107)]))}const b=l(r,[["render",t]]);export{m as __pageData,b as default};
